[
  {
    "statement": "Several non-chemical alternatives exist for managing invasive water primrose.",
    "citations": []
  },
  {
    "statement": "Evidence for the effectiveness of non-chemical alternatives for managing invasive water primrose varies.",
    "citations": []
  },
  {
    "statement": "Biological control using co-evolved, host-specific herbivores shows promise for managing invasive water primrose.",
    "citations": []
  },
  {
    "statement": "Studies demonstrated that flea beetles caused heavy feeding destruction to water primrose seedlings.",
    "citations": []
  },
  {
    "statement": "Flea beetles significantly reduced water primrose abundance when introduced to ponds.",
    "citations": []
  },
  {
    "statement": "Physical removal through hand-pulling was found to eradicate smaller populations of water primrose when done from pond margins.",
    "citations": []
  },
  {
    "statement": "Hand pulling combined with raking failed to reduce water primrose abundance in larger populations.",
    "citations": []
  },
  {
    "statement": "Other proposed non-chemical methods for managing water primrose include flame treatment, use of bottom mats, environmental control (shading, altered flow, dredging), and bank excavation.",
    "citations": []
  },
  {
    "statement": "No evidence was found documenting the effectiveness of methods like flame treatment, use of bottom mats, environmental control, and bank excavation.",
    "citations": []
  },
  {
    "statement": "Biological control using fungal-based herbicides lacks supporting evidence for its use.",
    "citations": []
  }
]

[
  {
    "statement": "Evidence from laboratory studies indicates that altering water properties can effectively control invasive Asian clams and Ponto-Caspian gammarids.",
    "citations": []
  },
  {
    "statement": "A controlled laboratory study in the USA found that 100% mortality occurred when Asian clams were exposed to high salinities ranging from 18-34‰.",
    "citations": [
      "1115"
    ]
  },
  {
    "statement": "Temperatures of 36°C or higher killed Asian clams within four days in controlled laboratory conditions.",
    "citations": [
      "1116"
    ]
  },
  {
    "statement": "For Ponto-Caspian gammarids, a UK laboratory study demonstrated that heating water to temperatures above 36°C killed all shrimps after 15 minutes of exposure.",
    "citations": [
      "1092"
    ]
  },
  {
    "statement": "A UK laboratory study found that water temperatures exceeding 43°C caused immediate death to Ponto-Caspian gammarids.",
    "citations": [
      "1092"
    ]
  },
  {
    "statement": "Regarding salinity control for Ponto-Caspian gammarids, mixed results were observed.",
    "citations": [
      "1091"
    ]
  },
  {
    "statement": "One replicated laboratory study in Canada and the UK found that increasing salinity levels killed the majority of invasive shrimp within five hours.",
    "citations": [
      "1091"
    ]
  },
  {
    "statement": "Another study found that increased salinity did not kill invasive killer shrimp.",
    "citations": [
      "1091"
    ]
  }
]

[
  {
    "statement": "The primary effective alternative to biocides for controlling invasive brown and black bullhead populations in shallow European ponds is the use of double fyke nets.",
    "citations": []
  },
  {
    "statement": "Double fyke nets can be used to significantly reduce the population of brown bullhead measuring over 8cm.",
    "citations": []
  },
  {
    "statement": "Other potential alternatives for controlling bullhead populations include draining invaded waterbodies, combined netting and electrofishing approaches, and trapping using sound or pheromonal lures.",
    "citations": []
  },
  {
    "statement": "Other potential alternatives for controlling bullhead populations include biological control using native predators and environmental modifications such as changing pH or salinity.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of alternative methods such as draining waterbodies, combined netting and electrofishing, trapping, biological control, and environmental modifications.",
    "citations": []
  },
  {
    "statement": "No studies have directly and quantitatively tested the effectiveness of draining waterbodies, combined netting and electrofishing, trapping, biological control, or environmental modifications for bullhead control.",
    "citations": []
  }
]

[
  {
    "statement": "The most effective non-physical control methods for Crassula helmsii in the UK are chemical herbicides, particularly glyphosate and diquat.",
    "citations": []
  },
  {
    "statement": "Studies have found that glyphosate reduced Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "A 98% reduction in Crassula helmsii was shown when glyphosate was applied in combination with diquat.",
    "citations": []
  },
  {
    "statement": "Covering Crassula helmsii with carpet before treating with glyphosate resulted in an 80% reduction of the plant.",
    "citations": []
  },
  {
    "statement": "Applying diquat or diquat alginate was found to reduce cover or eradicate submerged Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "Other herbicides showing partial effectiveness against Crassula helmsii include dichlobenil, terbutryne, asulam, 2,4-D amine and dalapon.",
    "citations": []
  },
  {
    "statement": "The least effective non-physical control method documented for Crassula helmsii is hydrogen peroxide.",
    "citations": []
  },
  {
    "statement": "One controlled study found that hydrogen peroxide did not control Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "There is no evidence found for the biological control of Crassula helmsii using herbivores.",
    "citations": []
  },
  {
    "statement": "There is no evidence found for using hot water treatment to control Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "The effectiveness of using biological control with herbivores or hot water treatment for Crassula helmsii has not been tested.",
    "citations": []
  }
]

[
  {
    "statement": "For the invasive plant Crassula helmsii, using salt water is one of the most promising eradication methods based on evidence.",
    "citations": [
      "1288"
    ]
  },
  {
    "statement": "Salt water was found to eradicate Crassula helmsii in replicated controlled container trials and in before-and-after field trials in the UK.",
    "citations": [
      "1288"
    ]
  },
  {
    "statement": "Lightproof barriers have also shown effectiveness against Crassula helmsii.",
    "citations": [
      "1294"
    ]
  },
  {
    "statement": "Five before-and-after studies in the UK found that covering Crassula helmsii with black sheeting or carpet strips eradicated or severely reduced the plant's coverage.",
    "citations": [
      "1294"
    ]
  },
  {
    "statement": "Recolonization of Crassula helmsii occurred at two sites where lightproof barriers were used.",
    "citations": [
      "1294"
    ]
  },
  {
    "statement": "A combination approach using carpet covering followed by glyphosate herbicide treatment killed 80% of Crassula helmsii in one UK pond study.",
    "citations": [
      "1313"
    ]
  },
  {
    "statement": "For skunk cabbage, chemical control using herbicides has shown mixed results.",
    "citations": [
      "1102"
    ]
  },
  {
    "statement": "One UK study found that both glyphosate and 2,4-D Amine killed all skunk cabbage plants in test areas.",
    "citations": [
      "1102"
    ]
  },
  {
    "statement": "Another UK study showed that 2,4-D amine at 9 litres/ha successfully eradicated skunk cabbage.",
    "citations": [
      "1102"
    ]
  },
  {
    "statement": "In one UK study, glyphosate only achieved a limited reduction in skunk cabbage growth.",
    "citations": [
      "1102"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of draining waterbodies for the eradication of Crassula helmsii.",
    "citations": [
      "1303"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of physical or manual removal methods for the eradication of Crassula helmsii.",
    "citations": [
      "1278"
    ]
  }
]

[
  {
    "statement": "Several methods are available for managing biofouling by Asian clams in industrial water systems.",
    "citations": []
  },
  {
    "statement": "Chemical treatments have shown effectiveness in managing Asian clams.",
    "citations": []
  },
  {
    "statement": "Biocides including chlorine, potassium, and copper can kill Asian clams.",
    "citations": []
  },
  {
    "statement": "Higher concentrations of chlorine and bromine delivered at elevated temperatures reduce the time required for the chemicals to be effective.",
    "citations": []
  },
  {
    "statement": "BioBullets are fat-coated particles that have been shown to kill 100% of Asian clams within pipes in irrigation systems.",
    "citations": []
  },
  {
    "statement": "Physical methods for managing Asian clams include mechanical removal and regular cleaning of industrial pipes.",
    "citations": []
  },
  {
    "statement": "Mechanical removal and regular cleaning of industrial pipes are effective for the permanent removal or reduction of Asian clam populations.",
    "citations": []
  },
  {
    "statement": "The addition of sand filters has proven effective for reducing Asian clam numbers.",
    "citations": []
  },
  {
    "statement": "Temperature modification is a viable approach for managing Asian clams.",
    "citations": []
  },
  {
    "statement": "Water temperatures of 36°C or higher can kill Asian clams within four days.",
    "citations": []
  },
  {
    "statement": "Mechanical removal techniques like suction dredging have been effective in managing Asian clams in some settings.",
    "citations": []
  },
  {
    "statement": "Oxygen reduction methods have shown limited effectiveness for managing Asian clams.",
    "citations": []
  },
  {
    "statement": "Asian clams demonstrate resistance to extremely low oxygen levels.",
    "citations": []
  }
]

[
  {
    "statement": "There is no documented evidence for the effectiveness of draining water bodies for controlling Asian clams or Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "Gas-impermeable barriers placed across lake bottoms significantly reduced Asian clam abundance in a controlled North American study.",
    "citations": []
  },
  {
    "statement": "Lightproof barriers, such as black sheeting or carpet strips, eradicated or severely reduced Crassula helmsii cover in five UK studies.",
    "citations": []
  },
  {
    "statement": "Recolonization of Crassula helmsii occurred at two of the five UK study sites where lightproof barriers were used.",
    "citations": []
  }
]

[
  {
    "statement": "For Procambarus crayfish, limited evidence exists for biological control through encouraging predators.",
    "citations": []
  },
  {
    "statement": "Two replicated, controlled studies in Italy found that eels fed on red swamp crayfish and reduced the crayfish's population size.",
    "citations": []
  },
  {
    "statement": "One replicated, controlled study from France in 2001 found that pike predated red swamp crayfish.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "For Ponto-Caspian gammarids, the evidence for biological control is minimal.",
    "citations": []
  },
  {
    "statement": "One replicated laboratory study in Canada found that an introduced parasitic mould reduced populations of an invasive shrimp.",
    "citations": [
      "1089"
    ]
  },
  {
    "statement": "No evidence was captured for using predatory fish to control Ponto-Caspian gammarids.",
    "citations": [
      "1087"
    ]
  },
  {
    "statement": "No evidence was captured for using disease-causing organisms to control Ponto-Caspian gammarids.",
    "citations": [
      "1090"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of using biological control to manage non-native, invasive or other problematic species populations on subtidal benthic invertebrate populations.",
    "citations": [
      "2172"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of using biological control to manage non-native, invasive or other problematic species populations on marine and freshwater mammal populations.",
    "citations": [
      "2852"
    ]
  },
  {
    "statement": "Host-specific biological control using co-evolved herbivores has shown success in controlling some invasive plants like water primrose.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "The approach of using host-specific biological control with co-evolved herbivores has not been documented for invasive invertebrates like crayfish or gammarids.",
    "citations": []
  }
]

[
  {
    "statement": "Several factors influence the success of chemical control for invasive plants.",
    "citations": []
  },
  {
    "statement": "For skunk cabbage, the choice of herbicide is critical.",
    "citations": [
      "1102"
    ]
  },
  {
    "statement": "Studies show conflicting results for using glyphosate to control skunk cabbage.",
    "citations": [
      "1102"
    ]
  },
  {
    "statement": "One UK study found that glyphosate achieved a complete kill of skunk cabbage.",
    "citations": [
      "1102"
    ]
  },
  {
    "statement": "Another study found that glyphosate resulted in only a limited reduction in skunk cabbage growth.",
    "citations": [
      "1102"
    ]
  },
  {
    "statement": "The herbicide 2,4-D amine consistently achieved eradication of skunk cabbage when applied at 9 litres per hectare.",
    "citations": [
      "1102"
    ]
  },
  {
    "statement": "Multiple factors for success emerge in the control of water primrose.",
    "citations": [
      "1139",
      "1140"
    ]
  },
  {
    "statement": "Herbicide selection is an important factor in managing water primrose.",
    "citations": [
      "1139"
    ]
  },
  {
    "statement": "Triclopyr TEA achieved a 100% kill of young water primrose plants at a 0.25% concentration.",
    "citations": [
      "1139"
    ]
  },
  {
    "statement": "Glyphosate achieved 97% mortality of water primrose when mixed with non-oil based sticking agents.",
    "citations": [
      "1139"
    ]
  },
  {
    "statement": "Glyphosate achieved 100% mortality of water primrose when mixed with TopFilm.",
    "citations": [
      "1139"
    ]
  },
  {
    "statement": "Halosulfuron-methyl provided significant coverage reduction of water primrose without harming rice plants.",
    "citations": [
      "1139"
    ]
  },
  {
    "statement": "The method of chemical application affects treatment outcomes.",
    "citations": [
      "1140"
    ]
  },
  {
    "statement": "A treatment of glyphosate with Cygnet-Plus combined with mechanical removal achieved only a 75% kill rate.",
    "citations": [
      "1140"
    ]
  },
  {
    "statement": "Combination approaches using herbicide, physical removal, native plant promotion, and mulching reduced Peruvian primrose-willow coverage by 85-90%.",
    "citations": [
      "1140"
    ]
  }
]

[
  {
    "statement": "Concrete barrier dams with specific design features can effectively contain red swamp crayfish populations upstream.",
    "citations": []
  },
  {
    "statement": "The design of concrete barrier dams can prevent crayfish from crawling over the dams.",
    "citations": []
  },
  {
    "statement": "Chemical treatments such as iodine solution, acetic acid, Virkon S, and sodium hypochlorite can kill invasive killer shrimp in freshwater.",
    "citations": []
  },
  {
    "statement": "The chemical treatments available to kill invasive killer shrimp are considered impractical for field use.",
    "citations": []
  },
  {
    "statement": "Carbonating water stuns invasive killer shrimp.",
    "citations": []
  },
  {
    "statement": "Exposure to predators slows the movement of invasive freshwater shrimp.",
    "citations": []
  },
  {
    "statement": "Electrical barriers used for invasive fish show potential for preventing movement of invasive species.",
    "citations": []
  },
  {
    "statement": "Electrical barriers could be adapted for use against invertebrates.",
    "citations": []
  }
]

[
  {
    "statement": "For controlling invasive red swamp crayfish (Procambarus clarkii) in European ponds, several non-chemical management strategies have been studied.",
    "citations": []
  },
  {
    "statement": "Evidence indicates that trapping red swamp crayfish with food bait, such as tinned meat, is more effective than using pheromones or unbaited traps.",
    "citations": [
      "1029"
    ]
  },
  {
    "statement": "Over half of all red swamp crayfish were caught in food-baited traps.",
    "citations": [
      "1029"
    ]
  },
  {
    "statement": "Creating physical barriers with concrete dams, specifically designed to prevent red swamp crayfish from crawling over them, has been shown to effectively contain population spread upstream in Spain.",
    "citations": [
      "1037"
    ]
  },
  {
    "statement": "Combining trapping with predator encouragement has demonstrated significant reductions in red swamp crayfish populations.",
    "citations": [
      "1031"
    ]
  },
  {
    "statement": "A Swiss study found that introducing predators combined with trapping significantly reduced red swamp crayfish populations.",
    "citations": [
      "1031"
    ]
  },
  {
    "statement": "An Italian study showed that combining trapping with predation was more effective at reducing red swamp crayfish populations than predation alone.",
    "citations": [
      "1031"
    ]
  },
  {
    "statement": "Natural predation by eels has been shown to reduce red swamp crayfish populations in Italian studies.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "Pike also predate on red swamp crayfish according to French research.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "Sterilization of male red swamp crayfish through X-ray exposure reduced offspring production by 43% in laboratory studies.",
    "citations": [
      "1032"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of draining waterways as a control method for red swamp crayfish.",
    "citations": [
      "1034"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of electrofishing as a control method for red swamp crayfish.",
    "citations": [
      "1035"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of removing food sources as a control method for red swamp crayfish.",
    "citations": [
      "1033"
    ]
  }
]

[
  {
    "statement": "The evidence for using physical barriers to control invasive species movement varies significantly by species type.",
    "citations": []
  },
  {
    "statement": "A before-and-after study in Spain found that concrete dams designed with features to prevent red swamp crayfish from crawling over the dams were effective at containing the crayfish population's spread upstream.",
    "citations": [
      "1037"
    ]
  },
  {
    "statement": "A controlled, replicated field study in the USA found that electrical barriers prevented the movement of Ponto-Caspian gobies across the barriers.",
    "citations": [
      "1074"
    ]
  },
  {
    "statement": "The effectiveness of electrical barriers in preventing the movement of Ponto-Caspian gobies increased at higher electrical pulse durations and voltages.",
    "citations": [
      "1074"
    ]
  },
  {
    "statement": "No evidence was found regarding the use of lightproof barriers for the aquatic plant parrot's feather.",
    "citations": [
      "1576"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of covers or barriers for problematic plants in peatlands.",
    "citations": [
      "1775"
    ]
  },
  {
    "statement": "For Ponto-Caspian gammarids, research focused more on behavioral deterrents using predator cues rather than on physical barriers.",
    "citations": [
      "1088"
    ]
  }
]

[
  {
    "statement": "For American bullfrogs, direct removal techniques include trapping using double fyke nets.",
    "citations": [
      "1046"
    ]
  },
  {
    "statement": "Double fyke nets were found effective in catching American bullfrog tadpoles in small shallow ponds in Belgium.",
    "citations": [
      "1046"
    ]
  },
  {
    "statement": "Adult American bullfrog removal techniques include using single traps floating on the water surface overnight in small ponds in the USA.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "The catchability of adult American bullfrogs using double fyke nets was found to be very low.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "Shooting metamorphosed American bullfrogs before reproduction was used as part of combination treatments in France.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "Shooting metamorphosed American bullfrogs resulted in a significant reduction in recorded adults and juveniles.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "One study found that American bullfrog populations rapidly rebounded following intensive removal of adults.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "For red-eared terrapins, Aranzadi turtle traps were found effective for trapping adults from rivers in Spain.",
    "citations": [
      "1055"
    ]
  },
  {
    "statement": "Aranzadi turtle traps did not eradicate the red-eared terrapin population in the area where the traps were used.",
    "citations": [
      "1055"
    ]
  },
  {
    "statement": "Sein nets were used to trap adult and juvenile red-eared terrapins in the British Virgin Islands.",
    "citations": [
      "1055"
    ]
  },
  {
    "statement": "Sein nets were not successful in eradicating the red-eared terrapin population.",
    "citations": [
      "1055"
    ]
  },
  {
    "statement": "Draining invaded waterbodies was considered as a removal technique for red-eared terrapins.",
    "citations": [
      "1057"
    ]
  },
  {
    "statement": "No evidence was found on the impact of draining invaded waterbodies on red-eared terrapin population reduction.",
    "citations": [
      "1057"
    ]
  },
  {
    "statement": "Both American bullfrog and red-eared terrapin species showed rapid population recovery following removal efforts.",
    "citations": [
      "1045",
      "1055"
    ]
  },
  {
    "statement": "Sustained and repeated removal efforts are necessary for effective control of American bullfrogs and red-eared terrapins.",
    "citations": []
  }
]

[
  {
    "statement": "The documented outcomes of physical and chemical control methods for floating pennywort show mixed effectiveness.",
    "citations": []
  },
  {
    "statement": "Physical removal of floating pennywort alone was found to be insufficient.",
    "citations": [
      "1126"
    ]
  },
  {
    "statement": "A two-week removal program for floating pennywort in Western Australia showed that the plant's growth rate exceeded the removal rate.",
    "citations": [
      "1126"
    ]
  },
  {
    "statement": "Mechanical removal of floating pennywort combined with monthly hand picking in the UK greatly reduced the plant's coverage.",
    "citations": [
      "1126"
    ]
  },
  {
    "statement": "Mechanical removal of floating pennywort combined with monthly hand picking did not achieve complete eradication.",
    "citations": [
      "1126"
    ]
  },
  {
    "statement": "For chemical control of floating pennywort, the herbicide 2,4-D amine applied at 4.2 kg/ha demonstrated the highest effectiveness, achieving near 100% mortality.",
