      "1129"
    ]
  },
  {
    "statement": "A 30% concentration of hydrogen peroxide caused leaf curling and transparency in floating pennywort but was insufficient to kill the plants.",
    "citations": [
      "1129"
    ]
  },
  {
    "statement": "No evidence was found for biological control of floating pennywort using fungal-based herbicides.",
    "citations": [
      "1125"
    ]
  }
